private static char decodeHexNibble(final char c) {
    try {
        if ('0' <= c && c <= '9') {
            return (char) (c - '0');
        } else if ('a' <= c && c <= 'f') {
            return (char) (c - 'a' + 10);
        } else if ('A' <= c && c <= 'F') {
            return (char) (c - 'A' + 10);
        } else {
            throw new IllegalArgumentException("Invalid hex character: " + c);
        }
    } catch (IllegalArgumentException e) {
        throw new IllegalArgumentException("Invalid hex character: " + c, e);
    }
}

