private static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            // parse the line into a ThreadSnapshot object
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(line);
            // check if the thread snapshot's timestamp falls within the given time ranges
            boolean withinTimeRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (threadSnapshot.getTimestamp() >= timeRange.getStartTime() && threadSnapshot.getTimestamp() <= timeRange.getEndTime()) {
                    withinTimeRange = true;
                    break;
                }
            }
            if (withinTimeRange) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    return threadSnapshots;
}

