public static JsonObject convertProperties(List<KeyStringValuePair> properties) {
    JsonObject jsonObject = new JsonObject();
    if (properties != null && !properties.isEmpty()) {
        for (KeyStringValuePair pair : properties) {
            String key = pair.getKey().toLowerCase();
            String value = pair.getValue();
            switch (key) {
                case "integer":
                    jsonObject.put(key, Integer.parseInt(value));
                    break;
                case "string":
                    jsonObject.put(key, value);
                    break;
                case "float":
                    jsonObject.put(key, Float.parseFloat(value));
                    break;
                case "double":
                    jsonObject.put(key, Double.parseDouble(value));
                    break;
                case "boolean":
                    jsonObject.put(key, Boolean.parseBoolean(value));
                    break;
                default:
                    jsonObject.put(key, value);
            }
        }
    }
    return jsonObject;
}

