public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    for (int i = index; i < index + len; ++i) {
        char c = str.charAt(i);
        if (c < 0x0080) {
            size += 1;
        } else if (c < 0x0800) {
            size += 2;
        } else if (c < 0x10000) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

