        builder.append(str);
        byte[] utf8Bytes = builder.toString().getBytes(StandardCharsets.UTF_8);
        int length = utf8Bytes.length;
        lb.putString(String.valueOf(length));
        lb.put(new Utf8CharArray(utf8Bytes));
        session.next(length + lb.getPosition());
