public long readRawVarint64() throws IOException {
  long result = 0;
  int index = 0;
  while(true) {
    byte temp = stream.readByte();
    if (temp >= 0) {
      result |= (temp & 0x7F) << index;
      index += 7;
      if ((temp & 0x80) == 0) {
        return result;
      }
    } else {
      throw new IOException("Invalid Varint encoding");
    }
  }
}

