public int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        out.write(node.bytes, node.offset, node.limit - node.offset);
        totalSize += node.limit - node.offset;
        node = node.next;
    }
    return totalSize;
}

